c("https://img.sndimg.com/food/image/upload/w_555,h_416,c_fit,fl_progressive,q_95/v1/img/recipes/13/27/5/rGqvyQubS368wqCdLz0A_Christmas Cardamom Butter Cookies_0338.JPG", "https://img.sndimg.com/food/image/upload/v1/img/feed/13275/ViNPSE9mRzmmhHhD8fYt_57968E8A-07C8-4372-8EAB-A6145C8152CB.jpeg", "https://img.sndimg.com/food/image/upload/w_555,h_416,c_fit,fl_progressive,q_95/v1/img/recipes/13/27/5/7dkaOaaThiICtoaBFd5k_Christmas Cardamom Butter Cookies_0339.JPG", "https://img.sndimg.com/food/image/upload/w_555,h_416,c_fit,fl_progressive,q_95/v1/img/recipes/13/27/5/HTyl2vISFqAAcvHRgGaq-Cardamom-Butter-Cookies.JPG", 
